(async()=>{
  'use strict';
  const q=new URLSearchParams(location.search),scenario=q.get('scenario'),language=q.get('lang')==='en'?'en':'es',runId=q.get('run'),token=q.get('token'),ACL=window.VAAKAccess,F=window.VAAKFixtures,R=window.VAAKRuntime;
  const tr=(es,en)=>language==='es'?es:en,copy=v=>JSON.parse(JSON.stringify(v));
  const memory=new Map(),storage={getItem:k=>memory.has(k)?memory.get(k):null,setItem:(k,v)=>memory.set(k,String(v)),removeItem:k=>memory.delete(k)};
  let state=F.seed();storage.setItem(R.STORE,JSON.stringify(state));storage.setItem(R.SESSION,'admin');
  const runtime=R.createRuntime({storage,language:()=>language});runtime.setRoute('users');let pass=true,assertionKeys=[],title='',subtitle='',cards=[];
  const assert=(key,value,label)=>{assertionKeys.push(key);pass=pass&&!!value;cards.push({label,value:!!value})};
  if(scenario==='01-new-worker-unconfirmed'){title=tr('Nuevo trabajador: revisión pendiente','New worker: review pending');let r=runtime.dispatchAction({action:'new-user',phase:'open'});assert('new-disabled-initial',r.ok&&r.descriptor.draft.confirmedRevision<r.descriptor.draft.revision,tr('Guardar permanece bloqueado','Save remains disabled'))}
  else if(scenario==='02-new-worker-confirmed'){title=tr('Nuevo trabajador: accesos confirmados','New worker: access confirmed');let r=runtime.dispatchAction({action:'new-user',phase:'open'}),c=runtime.dispatchAction({action:'confirm-access-review',phase:'execute',operationToken:r.descriptor.operationToken});assert('new-confirm-enables',c.ok&&c.draft.confirmedRevision===c.draft.revision,tr('Revisión confirmada','Review confirmed'))}
  else if(scenario==='03-edit-client'){title=tr('Editar cliente y órdenes autorizadas','Edit client and authorized orders');let r=runtime.dispatchAction({action:'edit-user',phase:'open',targetId:'client-a',resource:{type:'user',id:'client-a'}});assert('flow-edit-client-es-en',r.ok&&r.descriptor.draft.clientOrderIds.includes('o1'),tr('Sólo orden vinculada O1','Only linked order O1'))}
  else if(scenario==='04-role-confirmation'){title=tr('Confirmación de cambio de rol','Role change confirmation');let r=runtime.dispatchAction({action:'edit-user',phase:'open',targetId:'worker',resource:{type:'user',id:'worker'}}),d=runtime.dispatchAction({action:'request-role-change',phase:'execute',operationToken:r.descriptor.operationToken,payload:{role:'Client'}});assert('role-request-no-change',d.ok&&d.draft.role==='Worker'&&d.draft.pendingDecision.value==='Client',tr('El rol no cambia sin confirmar','Role does not change before confirmation'))}
  else if(scenario==='05-tools-removal'){title=tr('Retirar Herramientas y accesos dependientes','Remove Tools and dependent access');let d=ACL.createAccessDraft(state.users[1],0);d=ACL.reduceAccessDraft(d,{type:'request-tools-remove'});d=ACL.reduceAccessDraft(d,{type:'confirm-tools-remove'});assert('tools-none-confirm-removes',!d.grants['section.tools']&&!d.grants['section.suppliers']&&!d.grants['section.specs'],tr('Dependencias retiradas','Dependencies removed'))}
  else if(scenario==='06-worker-foreign-denied'){title=tr('Acceso ajeno denegado al trabajador','Worker foreign access denied');storage.setItem(R.SESSION,'worker');let d=ACL.authorizeAction({state,user:state.users[1],action:'edit-supplier',phase:'open',route:'suppliers',targetId:'s-foreign'});assert('worker-foreign-denial',!d.allowed,tr('Proveedor de otro proyecto bloqueado','Foreign-project supplier blocked'))}
  else if(scenario==='07-client-own-cross'){title=tr('Aislamiento de documentos del cliente','Client document isolation');storage.setItem(R.SESSION,'client-a');assert('client-own-order',ACL.canReadClientOrder(state,state.users[2],'o1'),tr('Orden propia visible','Own order visible'));assert('client-cross-order',!ACL.canReadClientOrder(state,state.users[2],'o2'),tr('Orden ajena oculta','Foreign order hidden'))}
  else if(scenario==='08-recovery-no-admin'){title=tr('Recuperación por estado inválido','Recovery from invalid state');state.users=state.users.filter(x=>x.role!=='Admin');assert('no-admin',!ACL.validateState(state).ok,tr('Se detectó ausencia de administrador','Missing administrator detected'))}
  else if(scenario==='09-reset-confirmation'){title=tr('Confirmar restablecimiento local','Confirm local reset');state.users=state.users.filter(x=>x.role!=='Admin');storage.setItem(R.STORE,JSON.stringify(state));storage.removeItem(R.SESSION);let fresh=R.createRuntime({storage,language:()=>language});fresh.setRoute('recovery');let r=fresh.dispatchAction({action:'reset-demo',phase:'open'});assert('reset-open-zero-write',r.ok&&r.descriptor.kind==='reset-confirm',tr('Confirmación obligatoria antes de restablecer','Confirmation required before reset'))}
  else if(scenario==='10-no-access'){title=tr('Usuario sin accesos habilitados','User with no enabled access');state.users[1].access={version:2,grants:{}};storage.setItem(R.STORE,JSON.stringify(state));storage.setItem(R.SESSION,'worker');let fresh=R.createRuntime({storage,language:()=>language}),view=fresh.renderCurrentRoute();assert('no-access',view.status==='no_access',tr('Sólo se permite cerrar sesión','Only sign out remains available'))}
  else{pass=false;title=tr('Escenario desconocido','Unknown scenario');assert('known-scenario',false,title)}
  subtitle=tr('Verificación visual de autorización local VAAK','VAAK local authorization visual verification');
  const stateHash=String([...JSON.stringify(state)].reduce((a,c)=>(a*31+c.charCodeAt(0))>>>0,2166136261));
  document.documentElement.lang=language;document.querySelector('#harness').innerHTML=`<header class="bar"><div class="brand">VAAK</div><div class="actor">${tr('Entorno local · datos de prueba','Local environment · test data')}</div></header><section class="page"><div class="eyebrow">VAAK · ${scenario} · ${language.toUpperCase()}</div><h1 class="title">${title}</h1><p class="subtitle">${subtitle}</p><section class="panel"><span class="status ${pass?'':'deny'}">${pass?tr('VERIFICACIÓN CORRECTA','VERIFICATION PASSED'):tr('VERIFICACIÓN FALLIDA','VERIFICATION FAILED')}</span><div class="grid">${cards.map(c=>`<article class="card"><strong>${c.value?'✓':'✕'} ${c.label}</strong><small>${c.value?tr('Resultado esperado','Expected result'):tr('Revisar resultado','Review result')}</small></article>`).join('')}</div></section></section><footer class="footer"><span>REF VAAK-ACCESS-3-C · ${runId}</span><span class="marker">${pass?'PASS':'FAIL'}</span></footer>`;
  const resources=performance.getEntriesByType('resource').map(x=>x.name);let posted=false;try{let response=await fetch('/__result',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({runId,token,scenario,lang:language,pass,assertionKeys,stateHash,resources})});posted=response.ok}catch{posted=false}document.querySelector('#harness').dataset.harnessStatus=pass&&posted?'pass':'fail';
})();
